<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{useRouter}from'vue-router';import BrandLogo from'@/components/common/BrandLogo.vue';import ProductCard from'@/components/menu/ProductCard.vue';import CartSheet from'@/components/cart/CartSheet.vue';import{useCafe}from'@/stores/cafe';import{useToast}from'@/composables/useToast';import{num,price}from'@/utils/format';import type{Drink}from'@/types/cafe';const store=useCafe(),router=useRouter(),open=ref(false),tab=ref(''),{show}=useToast();const shown=computed(()=>store.drinks.filter(x=>x.cat===tab.value));const currentTableLabel=computed(()=>{const t=store.db.tables.find(x=>x.n===store.table);return t?.name||`طاولة ${num(store.table)}`});onMounted(async()=>{await store.load();tab.value=store.categories[0]?.id??''});function add(d:Drink){store.add(d.id);show(`تمت إضافة ${d.n} للسلة`)}async function submit(){try{const o=await store.placeOrder();open.value=false;store.reset();await router.push({name:'order',params:{id:o.id},query:{table:store.table}})}catch{show(store.error??'تعذر إرسال الطلب')}}</script><template><header class="chero"><div class="top"><BrandLogo/><span class="tbadge">▦ {{currentTableLabel}}</span></div><h1>قهوتك، على مزاجك ☕</h1><p>اختر طلبك وسيصلك إلى طاولتك</p><div class="cslider"><div class="cslide active"><img src="https://images.unsplash.com/photo-1509042239860-f550ce710b93?w=900&q=80" alt="قهوة"><div class="cslide-info"><b>خلطة عناية سامي</b><p>نكهة غنية محمصة بعناية</p></div></div></div></header><p v-if="store.error" class="error-banner">{{store.error}}</p><div v-if="store.loading" class="loading-state">جاري تحميل القائمة…</div><template v-else><nav class="tabs"><button v-for="c in store.categories" :key="c.id" class="ctab" :class="{on:tab===c.id}" @click="tab=c.id">{{c.n}}<span class="cn">{{num(store.drinks.filter(x=>x.cat===c.id&&x.on).length)}}</span></button></nav><h2 class="sec-t">{{store.categories.find(x=>x.id===tab)?.n}}</h2><section class="dlist"><ProductCard v-for="(d,i) in shown" :key="d.id" :drink="d" :quantity="store.cart[d.id]||0" :index="i" @add="add(d)" @remove="store.remove(d.id)"/></section></template><div v-if="store.count" class="cartbar on"><div class="inner"><span class="cc">🛍<span class="n">{{num(store.count)}}</span></span><span class="ci"><b>{{num(store.count)}} أصناف</b><small>اطلب من طاولتك مباشرة</small></span><span class="cpr">{{price(store.total)}}</span><button class="go" @click="open=true">عرض السلة ‹</button></div></div><CartSheet :open="open" :items="store.items" :count="store.count" :total="store.total" :table="store.table" :notes="store.notes" :submitting="store.submitting" @close="open=false" @add="store.add" @remove="store.remove" @update:notes="store.notes=$event" @submit="submit"/></template>
